-- Spoken RP follow-ups. Never /me: the WoW client supplies its own emote.
local _, addon = ...
-- Fully qualified addon table paths stay editable in RPTextStudio.
addon.localeData.frFR.generalTexts.AGREE = { gruppe = { "Pour une fois, nous sommes d'accord.", "Cet argument tient parfaitement debout." }, ziel = { "%s, je partage ton avis.", "%s: Cet argument tient parfaitement debout." } }
addon.localeData.frFR.generalTexts.AMAZE = { gruppe = { "Voilà qui me laisse sans voix.", "Par les étoiles, comment est-ce possible ?" }, ziel = { "%s, tu m'étonnes vraiment.", "%s: Par les étoiles, comment est-ce possible ?" } }
addon.localeData.frFR.generalTexts.ANGRY = { gruppe = { "Ma patience vient de quitter la pièce.", "N'essayez surtout pas de recommencer." }, ziel = { "%s, tu mets ma patience à rude épreuve.", "%s: N'essayez surtout pas de recommencer." } }
addon.localeData.frFR.generalTexts.ATTACKTARGET = { gruppe = { "Armes prêtes ! La cible est désignée.", "Plus de discours, gardez les yeux sur l'ennemi !" }, ziel = { "Sur %s ! Tenez la ligne !", "%s: Plus de discours, gardez les yeux sur l'ennemi !" } }
addon.localeData.frFR.generalTexts.BARK = { gruppe = { "Ouaf ! J'espère avoir été assez clair.", "Un chien comprend parfois mieux qu'un conseiller." }, ziel = { "%s, c'était assez clair pour toi ?", "%s: Un chien comprend parfois mieux qu'un conseiller." } }
addon.localeData.frFR.generalTexts.BASHFUL = { gruppe = { "Un peu moins d'attention me ferait plaisir.", "Je suis un héros, pas l'attraction du soir." }, ziel = { "%s, tu me fais rougir.", "%s: Je suis un héros, pas l'attraction du soir." } }
addon.localeData.frFR.generalTexts.BECKON = { gruppe = { "Approchez, nous parlerons mieux ici.", "Rassurez-vous, je n'ai encore mordu personne aujourd'hui." }, ziel = { "%s, approche et rejoins-nous !", "%s: Rassurez-vous, je n'ai encore mordu personne aujourd'hui." } }
addon.localeData.frFR.generalTexts.BEG = { gruppe = { "Un peu d'aide ferait des miracles.", "Je déteste demander deux fois, mais je peux faire une exception." }, ziel = { "%s, aie un peu de pitié.", "%s: Je déteste demander deux fois, mais je peux faire une exception." } }
addon.localeData.frFR.generalTexts.BELCH = { gruppe = { "Pardon. Mon repas avait visiblement un mot à dire.", "Un bon rôti aime parfois avoir le dernier mot." }, ziel = { "%s, j'espère que tu ne m'en voudras pas.", "%s: Un bon rôti aime parfois avoir le dernier mot." } }
addon.localeData.frFR.generalTexts.BITE = { gruppe = { "Toute menace n'a pas besoin d'une lame.", "Il me reste des dents et bien peu de patience." }, ziel = { "%s, garde tes distances avec mes dents.", "%s: Il me reste des dents et bien peu de patience." } }
addon.localeData.frFR.generalTexts.BLEED = { gruppe = { "Une simple égratignure. Particulièrement tenace.", "Qui a dit que les héros ne saignent jamais ?" }, ziel = { "%s, un bandage serait le bienvenu.", "%s: Qui a dit que les héros ne saignent jamais ?" } }
addon.localeData.frFR.generalTexts.BLINK = { gruppe = { "Ai-je bien vu ce que je viens de voir ?", "Mes yeux exigent une explication." }, ziel = { "%s, refais cela, mes yeux n'y croient pas.", "%s: Mes yeux exigent une explication." } }
addon.localeData.frFR.generalTexts.BLOW = { gruppe = { "Un baiser voyageur a besoin d'un bon vent.", "Que la brise emporte un geste affectueux." }, ziel = { "%s, ce baiser soufflé est pour toi.", "%s: Que la brise emporte un geste affectueux." } }
addon.localeData.frFR.generalTexts.BLUSH = { gruppe = { "Voilà qui était fort inattendu.", "Mes joues parlent plus vite que moi aujourd'hui." }, ziel = { "%s, tu ne me facilites pas la réponse.", "%s: Mes joues parlent plus vite que moi aujourd'hui." } }
addon.localeData.frFR.generalTexts.BOGGLE = { gruppe = { "Plusieurs mots me manquent à la fois.", "Mon esprit réclame une petite pause." }, ziel = { "%s, explique-moi ce qui se passe.", "%s: Mon esprit réclame une petite pause." } }
addon.localeData.frFR.generalTexts.BONK = { gruppe = { "Parfois un rappel demande un peu d'insistance.", "C'était une leçon, pas une déclaration de guerre." }, ziel = { "%s, retiens ce petit avertissement.", "%s: C'était une leçon, pas une déclaration de guerre." } }
addon.localeData.frFR.generalTexts.BORED = { gruppe = { "Quelqu'un pourrait rallumer l'aventure ?", "J'ai déjà contemplé des pierres plus passionnantes." }, ziel = { "%s, tu aurais une meilleure idée ?", "%s: J'ai déjà contemplé des pierres plus passionnantes." } }
addon.localeData.frFR.generalTexts.BOUNCE = { gruppe = { "Aucune chaise ne me retiendra aujourd'hui.", "Mes pieds semblent avoir leurs propres projets." }, ziel = { "%s, allez, bouge un peu !", "%s: Mes pieds semblent avoir leurs propres projets." } }
addon.localeData.frFR.generalTexts.BRB = { gruppe = { "Un petit détour, je reviens tout de suite.", "Garde ma place et la soupe au chaud." }, ziel = { "%s, je reviens dans un instant.", "%s: Garde ma place et la soupe au chaud." } }
addon.localeData.frFR.generalTexts.CACKLE = { gruppe = { "Ha ! Cela devient de plus en plus amusant.", "Je devrais peut-être moins m'en réjouir." }, ziel = { "%s, tu l'as bien cherché !", "%s: Je devrais peut-être moins m'en réjouir." } }
addon.localeData.frFR.generalTexts.CALM = { gruppe = { "Du calme. La précipitation ne sert à rien.", "Un esprit clair reste une arme fiable." }, ziel = { "%s, respire avant de répondre.", "%s: Un esprit clair reste une arme fiable." } }
addon.localeData.frFR.generalTexts.CHARGE = { gruppe = { "En avant ! La route ne va pas s'ouvrir toute seule.", "Les braves ne connaissent pas la marche arrière." }, ziel = { "Avec moi, %s ! C'est parti !", "%s: Les braves ne connaissent pas la marche arrière." } }
addon.localeData.frFR.generalTexts.CHEW = { gruppe = { "Cette ration mérite un examen minutieux.", "Qui mâche trop vite manque la moitié du goût." }, ziel = { "%s, tu en veux un morceau ?", "%s: Qui mâche trop vite manque la moitié du goût." } }
addon.localeData.frFR.generalTexts.CHICKEN = { gruppe = { "Cot cot ! C'était une retraite tactique, évidemment.", "Pas besoin d'être une poule pour voir le danger." }, ziel = { "%s, tu caquettes ou tu agis ?", "%s: Pas besoin d'être une poule pour voir le danger." } }
addon.localeData.frFR.generalTexts.CHUCKLE = { gruppe = { "C'était mieux que je ne l'espérais.", "Un petit rire sauve parfois une longue journée." }, ziel = { "%s, tu sais me remonter le moral.", "%s: Un petit rire sauve parfois une longue journée." } }
addon.localeData.frFR.generalTexts.COLD = { gruppe = { "Quelqu'un aurait une seconde paire de chaussettes ?", "Même mes pensées commencent à geler." }, ziel = { "%s, tu connais un endroit plus chaud ?", "%s: Même mes pensées commencent à geler." } }
addon.localeData.frFR.generalTexts.CONFUSED = { gruppe = { "La carte et la réalité ne sont pas d'accord.", "Je ne suis pas perdu. J'étudie les possibilités." }, ziel = { "%s, peux-tu m'expliquer le rapport ?", "%s: Je ne suis pas perdu. J'étudie les possibilités." } }
addon.localeData.frFR.generalTexts.CONGRATS = { gruppe = { "Tu as bien mérité cela par ton travail !", "Aujourd'hui nous pouvons compter nos victoires." }, ziel = { "%s, toutes mes félicitations !", "%s: Aujourd'hui nous pouvons compter nos victoires." } }
addon.localeData.frFR.generalTexts.COUGH = { gruppe = { "Cette poussière aurait mieux fait de rester dehors.", "Pardon, l'air est particulièrement désagréable aujourd'hui." }, ziel = { "%s, aurais-tu un peu d'eau ?", "%s: Pardon, l'air est particulièrement désagréable aujourd'hui." } }
addon.localeData.frFR.generalTexts.COWER = { gruppe = { "Un petit pas en arrière serait peut-être sage.", "Le courage et la témérité ne sont pas identiques." }, ziel = { "%s, viens plutôt derrière ce mur.", "%s: Le courage et la témérité ne sont pas identiques." } }
addon.localeData.frFR.generalTexts.CRACK = { gruppe = { "Les doigts sont prêts. Le reste doit suivre.", "Il est temps de se remettre en mouvement." }, ziel = { "%s, prêt pour un nouveau tour ?", "%s: Il est temps de se remettre en mouvement." } }
addon.localeData.frFR.generalTexts.CRINGE = { gruppe = { "On aurait pu faire cela avec plus d'élégance.", "Je vais faire semblant de n'avoir rien vu." }, ziel = { "%s, dis-moi que ce n'était pas ton plan.", "%s: Je vais faire semblant de n'avoir rien vu." } }
addon.localeData.frFR.generalTexts.CRY = { gruppe = { "Parfois les mots sont bien trop petits.", "Les larmes aussi ont besoin d'un chemin." }, ziel = { "%s, pardonne-moi. J'ai besoin d'un instant.", "%s: Les larmes aussi ont besoin d'un chemin." } }
addon.localeData.frFR.generalTexts.CURIOUS = { gruppe = { "Voilà qui promet une histoire intéressante.", "J'aimerais comprendre comment cela fonctionne." }, ziel = { "%s, raconte-m'en davantage.", "%s: J'aimerais comprendre comment cela fonctionne." } }
